		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop
  const int t = 32;

  #pragma omp parallel
  {
    #pragma omp for collapse(2)
    for (int i = 0; i < _PB_N; i += t)
      for (int j = 0; j < _PB_N; j += t)
        for (int ii = i; ii < i + t && ii < _PB_N; ii++)
          for (int jj = j; jj < j + t && jj < _PB_N; jj++)
            A[ii][jj] = A[ii][jj] + u1[ii] * v1[jj] + u2[ii] * v2[jj];

    #pragma omp for
    for (int ii = 0; ii < _PB_N; ii += t)
      for (int jj = 0; jj < _PB_N; jj += t)
        for (int j = jj; j < jj + t && j < _PB_N; j++)
          for (int i = ii; i < ii + t && i < _PB_N; i++)
            x[i] = x[i] + beta * A[j][i] * y[j];

    #pragma omp for
    for (int i = 0; i < _PB_N; i++)
      x[i] = x[i] + z[i];

    #pragma omp for collapse(2)
    for (int i = 0; i < _PB_N; i += t)
      for (int j = 0; j < _PB_N; j += t)
        for (int ii = i; ii < i + t && ii < _PB_N; ii++)
          for (int jj = j; jj < j + t && jj < _PB_N; jj++)
            w[ii] = w[ii] + alpha * A[ii][jj] * x[jj];
  }
#pragma endscop


